type ExportableCandidate = {
  candidateName?: string;
  email?: string;
  phone?: string;
  location?: string;
  yearsExperience?: string;
  skills?: string[];
  education?: string[];
  professionalSummary?: string;
  recruiterNotes?: string[];
};

export function buildCandidateExportFilename(candidateName: string | null | undefined, extension: "csv" | "pdf") {
  const sanitizedBase = (candidateName ?? "candidate")
    .normalize("NFKD")
    .replace(/[^a-z0-9]+/gi, "-")
    .replace(/^-+|-+$/g, "")
    .toLowerCase()
    .slice(0, 80);
  return `${sanitizedBase || "candidate"}-resume-parse.${extension}`;
}

export function buildCandidateResumeCsv(profile: ExportableCandidate) {
  const escape = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`;
  return [
    ["Candidate name", profile.candidateName], ["Email", profile.email], ["Phone", profile.phone], ["Location", profile.location], ["Experience", profile.yearsExperience], ["Skills", profile.skills?.join("; ")], ["Education", profile.education?.join("; ")], ["Summary", profile.professionalSummary], ["Review notes", profile.recruiterNotes?.join("; ")],
  ].map(row => row.map(escape).join(",")).join("\n");
}

export function buildCandidateResumePdfText(profile: ExportableCandidate) {
  return [
    `Candidate: ${profile.candidateName || "Not found"}`, `Email: ${profile.email || "Not found"}`, `Phone: ${profile.phone || "Not found"}`, `Location: ${profile.location || "Not found"}`, `Experience: ${profile.yearsExperience || "Not found"}`, `Skills: ${profile.skills?.join(", ") || "Not found"}`, `Education: ${profile.education?.join(", ") || "Not found"}`, `Summary: ${profile.professionalSummary || "Not found"}`, `Human review notes: ${profile.recruiterNotes?.join("; ") || "None"}`, "This AI extraction is a recruiter aid only. Confirm the source resume before acting; no hiring, work-authorization, or eligibility decision is made automatically.",
  ].join("\n\n");
}

