function formatReadinessStatus(status?: string | null) {
  const labels: Record<string, string> = {
    not_started: "Not started",
    details_requested: "Update submitted",
    human_review: "Human review",
    verified: "Review complete",
    expiry_watch: "Expiry watch",
  };
  return labels[status ?? "not_started"] ?? "Not started";
}

export function getAllowedNavigation(role: RoleKey) {
  return navItems.filter(item => item.roles.includes(role));
}

export function resolveWorkspacePage(role: RoleKey, requestedPage: string) {
  if (requestedPage === "Candidate detail") return ["Administrator", "Recruiter"].includes(role) ? requestedPage : "Overview";
  return getAllowedNavigation(role).some(item => item.label === requestedPage) ? requestedPage : "Overview";
}

export function resolveWorkspacePath(role: RoleKey, requestedPath: string) {
  if (getCandidateDetailIdFromPath(requestedPath) !== null) {
    return ["Administrator", "Recruiter"].includes(role) ? requestedPath : "/workspace";
  }
  const requestedPage = workspacePagesByPath[requestedPath] ?? "Overview";
  return resolveWorkspacePage(role, requestedPage) === requestedPage ? requestedPath : "/workspace";
}

export function countCompletedOnboardingTasks(tasks: Array<{ done: boolean }>) {
  return tasks.filter(task => task.done).length;
}

export function isFinanceRole(role: RoleKey) {
  return role === "Finance";
}

type RecruiterLaunchboardRow = {
  onboardingStage?: "not_started" | "profile_in_progress" | "manager_confirmation" | "ready_for_assignment" | "assigned" | null;
  managerConfirmed?: boolean | null;
  assignmentState?: "unassigned" | "pending" | "active" | "roll_off" | null;
};

export function getRecruiterHandoffIndicator(row: RecruiterLaunchboardRow) {
  if (row.onboardingStage === "manager_confirmation" && !row.managerConfirmed) return "Manager confirmation needed";
  if (row.onboardingStage === "ready_for_assignment" && row.assignmentState === "unassigned") return "Assignment handoff needed";
  if (row.assignmentState === "roll_off") return "Delivery handoff needed";
  if (row.assignmentState === "pending") return "Assignment follow-up";
  return "No handoff flagged";
}

export function formatCandidateReviewState(reviewState?: "pending_human_review" | "reviewed" | "archived" | string | null) {
  if (reviewState === "reviewed") return "Human reviewed";
  if (reviewState === "archived") return "Archived";
  return "Human review pending";
}

