  const FinanceCommercialDemoScope = () => <section className={`mt-5 rounded-2xl border p-5 ${isFinanceRole(activeRole) ? "border-[#bfeade] bg-[#f1fbf8]" : "border-[#dce7f3] bg-white"}`}><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-extrabold">Representative commercial data scope</p><p className="mt-1 text-xs text-[#7185a0]">These sample demonstration values are not persisted in the protected portal summary or a commercial database field.</p></div><Pill tone={isFinanceRole(activeRole) ? "green" : "slate"}>{isFinanceRole(activeRole) ? "Finance sample view" : "Masked"}</Pill></div><div className="mt-4 grid gap-3 sm:grid-cols-3">{[["Client bill rate", "$142/hr"], ["Consultant pay rate", "$92/hr"], ["Assignment contribution", "35.2%"]].map(([label, value]) => <div key={label} className="rounded-xl bg-white p-3 ring-1 ring-[#dfeae7]"><p className="text-[10px] font-bold text-[#7185a0]">{label}</p><p className="mt-2 font-mono-ui text-sm font-medium text-[#284968]">{isFinanceRole(activeRole) ? value : "••••••"}</p></div>)}</div><p className="mt-4 text-[10px] leading-4 text-[#6a819d]"><LockKeyhole className="mr-1 inline text-[#0b57d0]" size={12} /> No commercial action, payment, invoice, payroll, or accounting control is present.</p></section>;

